import{_ as a,o as e,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"工作流与多 Agent 总览","description":"说明工作流与多 Agent 模块的作用、学习目标、边界和推荐路径。","frontmatter":{"title":"工作流与多 Agent 总览","description":"说明工作流与多 Agent 模块的作用、学习目标、边界和推荐路径。"},"headers":[],"relativePath":"py-agent/workflow/index.md","filePath":"py-agent/workflow/index.md","lastUpdated":1785380441000}'),o={name:"py-agent/workflow/index.md"};function d(l,t,i,s,p,h){return e(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="工作流与多-agent-总览" tabindex="-1">工作流与多 Agent 总览 <a class="header-anchor" href="#工作流与多-agent-总览" aria-label="Permalink to &quot;工作流与多 Agent 总览&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本模块研究怎样把模型、工具和业务步骤组织为可预测、可恢复、可评测的执行系统。它先建立框架无关的工作流模型，再以 LangGraph 为主线学习状态图与持久执行，最后进入多 Agent 协作、跨系统协议和质量工程。</p><h2 id="_1-模块作用" tabindex="-1">1. 模块作用 <a class="header-anchor" href="#_1-模块作用" aria-label="Permalink to &quot;1. 模块作用&quot;">​</a></h2><p>单 Agent 适合在有限工具中动态选择下一步；当流程包含不可跳过的业务阶段、并行任务、人工审批、故障恢复或多个独立角色时，需要显式工作流。多 Agent 则是在工作流之上进一步分配上下文、工具和决策责任，不是默认更高级的方案。</p><h2 id="_2-学习目标" tabindex="-1">2. 学习目标 <a class="header-anchor" href="#_2-学习目标" aria-label="Permalink to &quot;2. 学习目标&quot;">​</a></h2><p>完成本模块后，你应该能够：</p><ol><li>区分普通函数编排、固定工作流、单 Agent 和多 Agent；</li><li>使用 State、Node、Edge、Command、Send 和 Reducer 构建 LangGraph；</li><li>设计路由、循环、并行和 Subgraph，并定义终止条件；</li><li>使用 Checkpoint、Interrupt 和 Durable Execution 恢复长工作流；</li><li>区分重试、幂等、补偿和事务边界；</li><li>比较 Router、Handoff、Supervisor、Worker、Planner 和 Executor 模式；</li><li>使用 LangGraph 或 Deep Agents 实现多 Agent，并理解 A2A 的跨系统边界；</li><li>测试执行路径、状态、协作轨迹、版本迁移和恢复行为。</li></ol><h2 id="_3-学习路径" tabindex="-1">3. 学习路径 <a class="header-anchor" href="#_3-学习路径" aria-label="Permalink to &quot;3. 学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>核心问题</th><th>学习结果</th></tr></thead><tbody><tr><td><a href="/py-agent/workflow/workflow-foundations/">工作流原理</a></td><td>工作流怎样表达状态和执行语义</td><td>建立框架无关模型</td></tr><tr><td><a href="/py-agent/workflow/langgraph-core/">LangGraph 核心</a></td><td>图、状态、节点和运行 API 怎样对应</td><td>能构建最小状态图</td></tr><tr><td><a href="/py-agent/workflow/control-flow-composition/">控制流与组合</a></td><td>怎样路由、循环、并行和复用子图</td><td>能表达复杂控制流</td></tr><tr><td><a href="/py-agent/workflow/durable-execution-recovery/">持久执行与恢复</a></td><td>怎样暂停、重放和处理故障</td><td>能构建可恢复流程</td></tr><tr><td><a href="/py-agent/workflow/multi-agent-patterns/">多 Agent 模式</a></td><td>什么时候以及怎样分配角色</td><td>能选择协作拓扑</td></tr><tr><td><a href="/py-agent/workflow/multi-agent-implementation/">多 Agent 实现与协议</a></td><td>怎样映射到框架和跨系统协议</td><td>能实现并比较方案</td></tr><tr><td><a href="/py-agent/workflow/workflow-quality/">工作流质量工程</a></td><td>怎样证明路径和协作正确</td><td>能建立测试与发布闭环</td></tr></tbody></table><h2 id="_4-核心边界" tabindex="-1">4. 核心边界 <a class="header-anchor" href="#_4-核心边界" aria-label="Permalink to &quot;4. 核心边界&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工作流：应用定义状态与不可跳过的控制结构</span></span>
<span class="line"><span>Agent：模型在受限能力中动态决定下一步</span></span>
<span class="line"><span>多 Agent：多个独立决策单元通过协议协作</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>可以把 Agent 放进工作流节点，也可以让工作流协调多个 Agent。无论采用哪种方式，权限、事务、停止和恢复都不能只依赖模型判断。</p><h2 id="_5-内容边界" tabindex="-1">5. 内容边界 <a class="header-anchor" href="#_5-内容边界" aria-label="Permalink to &quot;5. 内容边界&quot;">​</a></h2><p>本模块不重复 LangChain 模型、工具和 Middleware 基础，也不展开 RAG 与记忆数据链路。FastAPI、业务数据库、Redis 和后台任务在“Agent 应用工程”继续讨论；安全治理、系统级观测、成本容量和部署可靠性属于“质量与生产”。这里只处理工作流与多 Agent 特有的质量问题。</p><h2 id="_6-前置知识" tabindex="-1">6. 前置知识 <a class="header-anchor" href="#_6-前置知识" aria-label="Permalink to &quot;6. 前置知识&quot;">​</a></h2><p>开始前应掌握 Python 类型标注、异步与异常，理解 LangChain Messages、Tools、Agent State、Runtime Context，以及 Checkpointer 与 Store 的区别。</p><h2 id="_7-学习方法" tabindex="-1">7. 学习方法 <a class="header-anchor" href="#_7-学习方法" aria-label="Permalink to &quot;7. 学习方法&quot;">​</a></h2><p>对每张图都追踪四件事：节点读取什么 State、返回什么更新、下一条 Edge 怎样选择、失败后从哪里恢复。对多 Agent 再增加两个问题：谁拥有哪部分上下文，以及由谁决定终止。</p>`,19)])])}const u=a(o,[["render",d]]);export{g as __pageData,u as default};
